17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
38	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
39	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
48	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
68	    private static final int MAX_OWNERS_PER_CITY = 50;
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    private final TelephoneNormalizer telephoneNormalizer;
79	
80	    private final AddressNormalizer addressNormalizer;
81	
82	    public OwnerRestControllerV1(ClinicService clinicService,
83	                                 OwnerMapper ownerMapper,
84	                                 PetMapper petMapper,
85	                                 VisitMapper visitMapper,
86	                                 TelephoneNormalizer telephoneNormalizer,
87	                                 AddressNormalizer addressNormalizer) {
88	        this.clinicService = clinicService;
89	        this.ownerMapper = ownerMapper;
90	        this.petMapper = petMapper;
91	        this.visitMapper = visitMapper;
92	        this.telephoneNormalizer = telephoneNormalizer;
93	        this.addressNormalizer = addressNormalizer;
94	    }
95	
96	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
97	    @Override
98	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
99	        Collection<Owner> owners;
100	        if (lastName != null) {
101	            owners = this.clinicService.findOwnerByLastName(lastName);
102	        } else {
103	            owners = this.clinicService.findAllOwners();
104	        }
105	        if (owners.isEmpty()) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
114	        Owner owner = this.clinicService.findOwnerById(ownerId);
115	        if (owner == null) {
116	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
117	        }
118	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
124	        normalizeAndValidate(ownerFieldsDto);
125	        HttpHeaders headers = new HttpHeaders();
126	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
127	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
128	        owner.setNamesakeCount(countNamesakes(owner));
129	        assignHousehold(owner, ownerFieldsDto);
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
139	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
140	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
141	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
142	     * it; the email is canonicalized; and a missing registration date defaults to the current date. The payload is
143	     * mutated in place so the caller can map and save it directly.
144	     *
145	     * @param ownerFieldsDto the incoming owner payload, mutated in place
146	     * @throws MissingOwnerFieldsException if any required field is missing or blank
147	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
148	     */
149	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
150	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
151	        validateRequiredFields(ownerFieldsDto);
152	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
153	        ownerFieldsDto.setTelephone(telephone);
154	        requireUniqueTelephone(telephone);
155	        requireUniqueHousehold(ownerFieldsDto);
156	        requireCityHasCapacity(ownerFieldsDto.getCity());
157	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
158	        if (ownerFieldsDto.getRegistrationDate() == null) {
159	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
160	        }
161	    }
162	
163	    /**
164	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
165	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
166	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
167	     * city (e.g. {@code LON-SMI-0007}).
168	     *
169	     * @param city     the owner's city
170	     * @param lastName the owner's last name
171	     * @return the generated customer code
172	     */
173	    private String generateCustomerCode(String city, String lastName) {
174	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
175	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
176	        int sequence = (int) this.clinicService.findAllOwners().stream()
177	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
178	            .count() + 1;
179	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
180	    }
181	
182	    /**
183	     * Counts how many existing owners already share the given owner's first and last name, compared
184	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
185	     * create; it is zero when the owner's name is unique.
186	     *
187	     * @param owner the newly mapped owner about to be saved
188	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
189	     */
190	    private int countNamesakes(Owner owner) {
191	        String firstName = owner.getFirstName();
192	        String lastName = owner.getLastName();
193	        return (int) this.clinicService.findAllOwners().stream()
194	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
195	                && lastName.equalsIgnoreCase(existing.getLastName()))
196	            .count();
197	    }
198	
199	    /**
200	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
201	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
202	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
203	     *
204	     * @param ownerFieldsDto the owner payload to validate
205	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
206	     */
207	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
208	        List<String> missingFields = new ArrayList<>();
209	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
210	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
211	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
212	        requireText(missingFields, "city", ownerFieldsDto.getCity());
213	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
214	        if (!missingFields.isEmpty()) {
215	            throw new MissingOwnerFieldsException(missingFields);
216	        }
217	    }
218	
219	    private void requireText(List<String> missingFields, String fieldName, String value) {
220	        if (value == null || value.isBlank()) {
221	            missingFields.add(fieldName);
222	        }
223	    }
224	
225	    /**
226	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
227	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
228	     * (blank or {@code null}) email is left untouched, since the field is optional.
229	     *
230	     * @param email the raw email value from the request, may be {@code null}
231	     * @return the lower-cased email, or the original value when none was supplied
232	     */
233	    private String normalizeEmail(String email) {
234	        if (email == null || email.isBlank()) {
235	            return email;
236	        }
237	        return email.toLowerCase();
238	    }
239	
240	    /**
241	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
242	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
243	     * originally formatted.
244	     *
245	     * @param telephone the normalized telephone of the owner being created
246	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
247	     */
248	    private void requireUniqueTelephone(String telephone) {
249	        boolean inUse = this.clinicService.findAllOwners().stream()
250	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
251	            .anyMatch(telephone::equals);
252	        if (inUse) {
253	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
254	        }
255	    }
256	
257	    /**
258	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
259	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
260	     *
261	     * @param city the city of the owner being created
262	     * @throws OwnerCityFullException if the city already contains 50 or more owners
263	     */
264	    private void requireCityHasCapacity(String city) {
265	        long cityOwners = this.clinicService.findAllOwners().stream()
266	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
267	            .count();
268	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
269	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
270	        }
271	    }
272	
273	    /**
274	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
275	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
276	     *
277	     * @param ownerFieldsDto the incoming owner payload
278	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
279	     *                                 set {@code sharesHousehold}
280	     */
281	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
282	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
283	            return;
284	        }
285	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
286	            throw new DuplicateOwnerException(
287	                "an owner with the same last name and address already exists in this household");
288	        }
289	    }
290	
291	    /**
292	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
293	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
294	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
295	     * incidental formatting differences and abbreviation variants do not affect membership.
296	     *
297	     * @param ownerFieldsDto the incoming owner payload
298	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
299	     *         them; empty when none match
300	     */
301	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
302	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
303	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
304	        return this.clinicService.findAllOwners().stream()
305	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
306	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
307	            .toList();
308	    }
309	
310	    /**
311	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
312	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
313	     *
314	     * @param value the raw field value, may be {@code null}
315	     * @return the whitespace-collapsed value, or an empty string when {@code null}
316	     */
317	    private String collapseWhitespace(String value) {
318	        if (value == null) {
319	            return "";
320	        }
321	        return value.strip().replaceAll("\\s+", " ");
322	    }
323	
324	    /**
325	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
326	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
327	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
328	     * identifier is derived deterministically from the household's last name and address, so every member of the same
329	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
330	     * feature and still lack the identifier are backfilled so the whole household shares it.
331	     *
332	     * @param owner          the newly mapped owner about to be saved
333	     * @param ownerFieldsDto the incoming owner payload
334	     */
335	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
336	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
337	            return;
338	        }
339	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
340	        if (members.isEmpty()) {
341	            return;
342	        }
343	        String householdId = generateHouseholdId(ownerFieldsDto);
344	        owner.setHouseholdId(householdId);
345	        for (Owner member : members) {
346	            if (!householdId.equals(member.getHouseholdId())) {
347	                member.setHouseholdId(householdId);
348	                this.clinicService.saveOwner(member);
349	            }
350	        }
351	    }
352	
353	    /**
354	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
355	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
356	     * of those fields, it is identical for every owner in the same household and never changes over time.
357	     *
358	     * @param ownerFieldsDto the incoming owner payload
359	     * @return the household identifier
360	     */
361	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
362	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
363	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
364	        try {
365	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
366	            StringBuilder hex = new StringBuilder();
367	            for (int i = 0; i < 6; i++) {
368	                hex.append(String.format("%02X", digest[i]));
369	            }
370	            return "HH-" + hex;
371	        } catch (NoSuchAlgorithmException ex) {
372	            throw new IllegalStateException("SHA-256 is not available", ex);
373	        }
374	    }
375	
376	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
377	    @Override
378	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
379	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
380	        if (currentOwner == null) {
381	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
382	        }
383	        currentOwner.setAddress(ownerFieldsDto.getAddress());
384	        currentOwner.setCity(ownerFieldsDto.getCity());
385	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
386	        currentOwner.setLastName(ownerFieldsDto.getLastName());
387	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
388	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
389	        this.clinicService.saveOwner(currentOwner);
390	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Transactional
395	    @Override
396	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
397	        Owner owner = this.clinicService.findOwnerById(ownerId);
398	        if (owner == null) {
399	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
400	        }
401	        this.clinicService.deleteOwner(owner);
402	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
403	    }
404	
405	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
406	    @Override
407	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
408	        Owner owner = this.clinicService.findOwnerById(ownerId);
409	        if (owner == null) {
410	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
411	        }
412	        HttpHeaders headers = new HttpHeaders();
413	        Pet pet = petMapper.toPet(petFieldsDto);
414	        owner.setId(ownerId);
415	        pet.setOwner(owner);
416	        pet.getType().setName(null);
417	        this.clinicService.savePet(pet);
418	        PetDto petDto = petMapper.toPetDto(pet);
419	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
420	            .buildAndExpand(pet.getId()).toUri());
421	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
422	    }
423	
424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Override
426	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
427	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
428	        if (currentOwner != null) {
429	            Pet currentPet = this.clinicService.findPetById(petId);
430	            if (currentPet != null) {
431	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
432	                currentPet.setName(petFieldsDto.getName());
433	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
434	                this.clinicService.savePet(currentPet);
435	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
436	            }
437	        }
438	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
439	    }
440	
441	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
442	    @Override
443	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
444	        HttpHeaders headers = new HttpHeaders();
445	        Visit visit = visitMapper.toVisit(visitFieldsDto);
446	        Pet pet = new Pet();
447	        pet.setId(petId);
448	        visit.setPet(pet);
449	        this.clinicService.saveVisit(visit);
450	        VisitDto visitDto = visitMapper.toVisitDto(visit);
451	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
452	            .buildAndExpand(visit.getId()).toUri());
453	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
454	    }
455	
456	
457	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
458	    @Override
459	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
460	        Owner owner = this.clinicService.findOwnerById(ownerId);
461	        if (owner != null) {
462	            Pet pet = owner.getPet(petId);
463	            if (pet != null) {
464	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
465	            }
466	        }
467	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
468	    }
469	}
