37	import org.springframework.web.bind.annotation.ExceptionHandler;
38	import org.springframework.web.bind.annotation.ResponseBody;
39	
40	/**
41	 * Global Exception handler for REST controllers.
42	 * <p>
43	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
44	 *
45	 * @author Vitaliy Fedoriv
46	 * @author Alexander Dudkin
47	 */
48	@ControllerAdvice
49	public class ExceptionControllerAdvice {
50	
51	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
52	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
53	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
54	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
55	
56	    /**
57	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
58	     * class.
59	     *
60	     * @param e     Object referring to the thrown exception.
61	     * @param status HTTP response status.
62	     * @param url URL request.
63	     */
64	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
65	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
66	        problemDetail.setType(URI.create(url.toString()));
67	        problemDetail.setTitle(e.getClass().getSimpleName());
68	        problemDetail.setDetail(detail);
69	        problemDetail.setProperty("timestamp", Instant.now());
70	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
71	        return problemDetail;
72	    }
73	
74	    /**
75	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
76	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
77	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
78	     * would catch it and report an authorization failure as a 500.
79	     *
80	     * @param e The {@link AccessDeniedException} to propagate
81	     * @throws AccessDeniedException always
82	     */
83	    @ExceptionHandler(AccessDeniedException.class)
84	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
85	        throw e;
86	    }
87	
88	    /**
89	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
90	     *
91	     * @param e The {@link Exception} to be handled
92	     * @param request {@link HttpServletRequest} object referring to the current request.
93	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
94	     */
95	    @ExceptionHandler(Exception.class)
96	    @ResponseBody
97	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
98	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
99	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
100	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
101	        return ResponseEntity.status(status).body(detail);
102	    }
103	
104	    /**
105	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
106	     * method returns a 404 Not Found status if an entity does not exist.
107	     *
108	     * @param e The {@link DataIntegrityViolationException} to be handled
109	     * @param request {@link HttpServletRequest} object referring to the current request.
110	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
111	     */
112	    @ExceptionHandler(DataIntegrityViolationException.class)
113	    @ResponseBody
114	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
115	        logger.warn("Data integrity violation at {} {}: {}",
116	            request.getMethod(),
117	            request.getRequestURI(),
118	            e.getMessage());
119	        logger.debug("Data integrity violation stacktrace", e);
120	        HttpStatus status = HttpStatus.NOT_FOUND;
121	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
122	        return ResponseEntity.status(status).body(detail);
123	    }
124	
125	    /**
126	     * Handles exception thrown by Bean Validation on controller methods parameters
127	     *
128	     * @param e The {@link MethodArgumentNotValidException} to be handled
129	     * @param request {@link HttpServletRequest} object referring to the current request.
130	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
131	     */
132	    @ExceptionHandler(MethodArgumentNotValidException.class)
133	    @ResponseBody
134	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
135	        HttpStatus status = HttpStatus.BAD_REQUEST;
136	        BindingResult bindingResult = e.getBindingResult();
137	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
138	        if (bindingResult.hasErrors()) {
139	            logger.debug("Validation error at {} {}: {}",
140	                request.getMethod(),
141	                request.getRequestURI(),
142	                bindingResult.getFieldErrors());
143	            detail.setProperty("schemaValidationErrors", schemaValidationErrors(bindingResult));
144	            detail.setProperty("errors", rejectedFieldNames(bindingResult));
145	        }
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles {@link MissingOwnerFieldsException}, thrown when a request to create or update an owner omits or leaves
151	     * blank one or more required fields. Reports the offending field names in the {@code errors} array of a
152	     * {@code 400 Bad Request} response.
153	     *
154	     * @param e The {@link MissingOwnerFieldsException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
157	     */
158	    @ExceptionHandler(MissingOwnerFieldsException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
161	        logger.debug("Missing or blank required fields at {} {}: {}",
162	            request.getMethod(),
163	            request.getRequestURI(),
164	            e.getFields());
165	        return errorResponse(e, HttpStatus.BAD_REQUEST, request, ERROR_INVALID_REQUEST, e.getFields());
166	    }
167	
168	    /**
169	     * Handles {@link InvalidTelephoneException}, thrown when an owner's telephone number cannot be converted into a
170	     * valid E.164 number (8 to 15 digits after the leading {@code '+'}). Returns a {@code 400 Bad Request} reporting the
